#!/usr/bin/env python3
"""M24.4d, decisive test: does Renode's `include @file` SLURP the whole file up front (so a later
overwrite of the same path cannot affect an already-started include), or does it stream/re-open
the file such that a concurrent writer can truncate away not-yet-executed later commands (here,
specifically `emulation CreateServerSocketTerminal ...` and `connector Connect ...`, which sit
after `machine LoadPlatformDescription` -- the one line already measured, in
`listener_race_probe.py`'s six clean isolated runs, to consume essentially all of the ~2.5s gap
between the `include` command's own reply and the terminal socket actually appearing)?

Single Renode process, single monitor connection -- no second process needed. Writes the FULL
resc (with the terminal lines) first, sends `include`, and *while that command is still being
serviced* (inside the same ~0.3-2.5s window `listener_race_probe.py` already measured) overwrites
the SAME path with a TRUNCATED version that stops right after `machine LoadPlatformDescription`,
deliberately omitting `CreateServerSocketTerminal`/`connector Connect` entirely. If the listener
still eventually appears, `include` must have already read the terminal-creating lines into memory
before the overwrite landed (execution decoupled from the file on disk). If the listener never
appears (confirmed by `lsof` polling, not inference), `include` streams the file lazily enough
that a same-path overwrite mid-flight can silently delete not-yet-reached commands -- exactly
`renode_bridge.py`'s own real hazard, since two nearly-simultaneous bridge processes write to the
identical hardcoded path (`third_party/renode/M24_4b/renode_bridge_generated.resc`).
"""
import sys
import threading
import time

sys.path.insert(0, "/Users/probe/code/AltaVista/third_party/renode/M24_4d")
import listener_race_probe as p  # noqa: E402

SCRATCH = p.SCRATCH


def main():
    monitor_port = p.free_tcp_port()
    uart_port = p.free_tcp_port()
    resc_path = f"{SCRATCH}/truncation_probe.resc"
    uart0_log = f"{SCRATCH}/truncation_probe_uart0.log"
    renode_log_path = f"{SCRATCH}/truncation_probe_renode_stdout.log"

    full_resc = f'''# generated by truncation_during_include_probe.py -- FULL version
:name: av-m24-4d-trunc
using sysbus
using sysbus.cluster0
using sysbus.cluster1
mach create "av-m24-4d-trunc"
machine LoadPlatformDescription @{p.PLATFORM}
uart0 CreateFileBackend @{uart0_log} true
emulation CreateServerSocketTerminal $uartport "uart1_bridge_trunc" false
connector Connect sysbus.uart1 uart1_bridge_trunc
macro reset
"""
    cluster0 ForEach IsHalted true
    cluster1 ForEach IsHalted true
    rpu0 IsHalted false
    sysbus LoadELF @{p.ELF} cpu=rpu0
"""
runMacro $reset
'''
    truncated_resc = f'''# generated by truncation_during_include_probe.py -- TRUNCATED version
# (deliberately omits CreateServerSocketTerminal/connector Connect entirely)
:name: av-m24-4d-trunc
using sysbus
using sysbus.cluster0
using sysbus.cluster1
mach create "av-m24-4d-trunc"
machine LoadPlatformDescription @{p.PLATFORM}
'''

    logf = open(renode_log_path, "wb")
    proc = p.subprocess.Popen(
        [p.RENODE_BIN, "--disable-gui", "--hide-log", "-P", str(monitor_port)],
        stdin=p.subprocess.DEVNULL, stdout=logf, stderr=p.subprocess.STDOUT,
    )
    print(f"renode pid={proc.pid} monitor_port={monitor_port} uart_port={uart_port}")
    try:
        t0 = time.monotonic()
        sock = p.wait_for_port("127.0.0.1", monitor_port, t0 + 30.0)
        mon = p.MonitorClient(sock)
        mon.sock.settimeout(10.0)
        try:
            mon.sock.recv(65536)
        except OSError:
            pass

        with open(resc_path, "w") as f:
            f.write(full_resc)
        mon.cmd(f"$uartport = {uart_port}")

        stop_event = threading.Event()
        samples = []
        poll_result = {}
        def poller():
            poll_result["first_listen_offset"] = p.poll_lsof_for_port(proc.pid, uart_port, stop_event, samples, budget_s=30.0)
        pt = threading.Thread(target=poller)
        pt.start()

        # Overwrite the SAME path with the truncated version on a delay timer, from a second
        # thread, WHILE mon.cmd(include...) below is still blocked waiting for its own reply
        # (which listener_race_probe.py already measured takes ~0.3s -- the overwrite is
        # scheduled at 0.15s, i.e. squarely inside that window, well before the ~2.5s point the
        # terminal-creating line actually executes).
        def overwrite_after_delay():
            time.sleep(0.15)
            t_overwrite = time.monotonic()
            with open(resc_path, "w") as f:
                f.write(truncated_resc)
            print(f"overwrote {resc_path} with TRUNCATED content at t+{t_overwrite - t_include_sent_holder[0]:.3f}s after include was sent")
        t_include_sent_holder = [time.monotonic()]
        ow_thread = threading.Thread(target=overwrite_after_delay)
        ow_thread.start()

        t_include_sent_holder[0] = time.monotonic()
        t_sent, chunks = mon.cmd(f"include @{resc_path}", idle_gap=0.3, timeout=20.0)
        include_text = p.clean(b"".join(c for _, c in chunks))
        print(f"include reply ({time.monotonic()-t_sent:.3f}s after send): {include_text!r}")
        ow_thread.join()

        # Wait generously and see whether the listener EVER appears.
        client = p.wait_for_port("127.0.0.1", uart_port, time.monotonic() + 20.0)
        print(f"tcp connect to uart_port succeeded: {client is not None}")
        if client is not None:
            client.close()
        time.sleep(3.0)
        stop_event.set()
        pt.join(timeout=10.0)
        print(f"lsof first_listen_offset: {poll_result.get('first_listen_offset')}")
        final_lines, _ = p.lsof_listen_ports(proc.pid)
        print(f"final lsof LISTEN lines for this pid: {final_lines}")

        # Extra: check monitor for any error message about the second (truncated) content, and
        # what machine state resulted -- did LoadPlatformDescription even run twice, is uart1
        # connected to anything at all now?
        extra = mon.cmd("connector Connections", idle_gap=0.5, timeout=5.0)
        print("connector Connections ->", p.clean(b"".join(c for _, c in extra[1]))[:500])
    finally:
        try:
            mon.send("quit")
        except Exception:
            pass
        try:
            proc.wait(timeout=10.0)
        except Exception:
            proc.kill()


if __name__ == "__main__":
    main()
